code:
# 模拟数据倾斜: 热 key 导致 Reduce 负载不均, 用加盐 + 两阶段聚合解决
NUM_REDUCERS = 3

def stable_hash(s):
    h = 0
    for c in s:
        h = (31 * h + ord(c)) & 0x7fffffff
    return h

def assign(key):
    return stable_hash(key) % NUM_REDUCERS

# 构造数据: 正常 key 各若干, hot_key 极多(倾斜)
data = []
for k in ["A", "B", "C"]:
    data += [(k, 1)] * 10
data += [("HOT", 1)] * 90   # 热 key 占 90%

# 阶段0: 无优化, 直接按 key 分区
load0 = {r: 0 for r in range(NUM_REDUCERS)}
for k, _ in data:
    load0[assign(k)] += 1
print("原始数据: A/B/C 各10条, HOT 90条 (共", len(data), "条)")
print("无优化 各 Reducer 负载(按 key 哈希分区):", load0)
print("=> 承载 HOT 的 Reducer 长尾卡住, 其余近乎空闲\n")

# 阶段1: 加盐(salting): 给 HOT 加 0..S-1 后缀打散
S = 3
salted = []
for i, (k, v) in enumerate(data):
    if k == "HOT":
        sk = f"HOT#{i % S}"
    else:
        sk = k
    salted.append((sk, v))
load1 = {r: 0 for r in range(NUM_REDUCERS)}
for k, _ in salted:
    load1[assign(k)] += 1
print(f"加盐后(S={S}) 各 Reducer 负载:", load1)
print("=> HOT 被均匀打散到", S, "个加盐键, 负载趋于均衡\n")

# 两阶段聚合
stage1 = {}
for k, v in salted:
    stage1[k] = stage1.get(k, 0) + v
stage2 = {}
for k, v in stage1.items():
    base = k.split("#")[0]
    stage2[base] = stage2.get(base, 0) + v
print("两阶段聚合最终结果:", dict(sorted(stage2.items())))
print("=> 与直接聚合结果一致(A=10,B=10,C=10,HOT=90), 但消除了单 Reducer 长尾")
